def collect_router_state():
    """Collect OSPF neighbors, routes, BGP from all routers."""
    results = {}
    def collect_one(name, params):
        conn = ConnectHandler(**params)
        data = {}
        if params["device_type"] == "vyos":
            for cmd in ["show ip ospf neighbor", "show ip route", "show ip bgp summary", "show ip bgp",
                        "show ip ospf interface", "show nat source rules"]:
                try:
                    data[cmd] = conn.send_command(cmd, read_timeout=30)
                except:
                    data[cmd] = ""
        else:
            for cmd in ["/routing ospf neighbor print detail", "/ip route print terse"]:
                try:
                    data[cmd] = conn.send_command(cmd, read_timeout=30)
                except:
                    data[cmd] = ""
        conn.disconnect()
        return name, data

    with ThreadPoolExecutor(max_workers=7) as pool:
        futures = [pool.submit(collect_one, n, p) for n, p in DEVICES.items()]
        for f in as_completed(futures):
            name, data = f.result()
            results[name] = data
    return results

def ping_test(src_name, src_params, targets):
    """Ping multiple targets from a host. Returns dict of target_ip: success."""
    conn = ConnectHandler(**src_params)
    results = {}
    for target_ip in targets:
        try:
            output = conn.send_command(f"ping -c 2 -W 3 {target_ip}", read_timeout=15)
            results[target_ip] = "0% packet loss" in output or "1 packets received" in output or "2 packets received" in output
        except Exception as e:
            results[target_ip] = False
    conn.disconnect()
    return src_name, results

