            ping_results[name] = res
            print(f"  [done] {name}", file=sys.stderr)

    # Non-guest to non-guest
    print("\nNon-guest to non-guest pings (expect all PASS):")
    ng_fails = []
    for src in NON_GUEST:
        for dst in NON_GUEST:
            if src == dst:
                continue
            dst_ip = HOST_IPS[dst]
            ok = ping_results[src].get(dst_ip, False)
            if not ok:
                ng_fails.append(f"  FAIL: {src} -> {dst} ({dst_ip})")
    if ng_fails:
        for f in ng_fails:
            print(f)
    else:
        print("  All 56 pairs PASS")

    # Guest to guest
    print("\nGuest to guest pings (expect PASS):")
    for src in GUEST:
        for dst in GUEST:
            if src == dst:
                continue
            dst_ip = HOST_IPS[dst]
            ok = ping_results[src].get(dst_ip, False)
            status = "PASS" if ok else "FAIL"
            print(f"  {src} -> {dst} ({dst_ip}): {status}")

    # Guest <-> non-guest (expect FAIL)
    print("\nGuest <-> non-guest pings (expect all FAIL = policy working):")
    policy_violations = []
    for src in GUEST:
        for dst in NON_GUEST:
            dst_ip = HOST_IPS[dst]
            ok = ping_results[src].get(dst_ip, False)
            if ok:
                policy_violations.append(f"  VIOLATION: {src} -> {dst} ({dst_ip}) should be blocked")
    for src in NON_GUEST:
        for dst in GUEST:
            dst_ip = HOST_IPS[dst]
            ok = ping_results[src].get(dst_ip, False)
            if ok:
                policy_violations.append(f"  VIOLATION: {src} -> {dst} ({dst_ip}) should be blocked")
    if policy_violations:
        for v in policy_violations:
            print(v)
    else:
        print("  All 32 pairs correctly blocked")

    # Internet reachability
    print("\nInternet pings (expect all PASS):")
    inet_fails = []
    for hname in list(HOST_IPS.keys()):
        for target in internet_targets:
            ok = ping_results[hname].get(target, False)
            if not ok:
                inet_fails.append(f"  FAIL: {hname} -> {target}")
    if inet_fails:
        for f in inet_fails:
            print(f)
    else:
        print("  All 20 pairs PASS (10 hosts x 2 targets)")

